/**
  * @brief  1ms periodic tasks
  */
static void Process_1ms_Tasks(void)
{
    system_tick++;

    // Process sensor readings
    Sensor_Process();

    // Process vehicle detection
    VehicleDetection_Process();
}

/**
  * @brief  10-minute periodic tasks
  */
static void Process_10min_Tasks(void)
{
    printf("\r\n[INFO] 10-minute interval reached. Preparing data transmission...\r\n");

    // Read environmental sensors
    Read_Temperature_Humidity();
    Read_Battery_Voltage();

    // Send data to server
    Send_Data_To_Server();

    // Reset statistics
    VehicleDetection_ResetInterval();
    lane1_count = 0;
    lane2_count = 0;

    last_send_time = system_tick;
}

/**
  * @brief  Read battery voltage via ADC
  */
static void Read_Battery_Voltage(void)
{
    uint32_t adc_value = 0;

    HAL_ADC_Start(&hadc1);
    if (HAL_ADC_PollForConversion(&hadc1, 100) == HAL_OK) {
        adc_value = HAL_ADC_GetValue(&hadc1);
        // Voltage divider: 12V -> 3.3V (R1=10k, R2=3.9k)
        // ADC 12-bit: 4095 = 3.3V
        // Actual voltage = (adc_value * 3.3 / 4095) * (10 + 3.9) / 3.9
        battery_voltage = (adc_value * 3.3f / 4095.0f) * 3.564f;
    }
    HAL_ADC_Stop(&hadc1);

    printf("[BATTERY] Voltage: %.2f V\r\n", battery_voltage);

    if (battery_voltage < 11.0f) {
        printf("[WARNING] Low battery voltage!\r\n");
    }
}

