/**
  * @brief  Send traffic data to server via SIM800L
  */
static void Send_Data_To_Server(void)
{
    char json_buffer[2048];
    int json_len = 0;

    // Get interval statistics
    const IntervalStats_t *stats = VehicleDetection_GetIntervalStats();

    const LaneStats_t *lane1 = &stats->lane[0];
    const LaneStats_t *lane2 = &stats->lane[1];

    // Build JSON payload
    json_len = snprintf(json_buffer, sizeof(json_buffer),
        "{"
        "\"device_id\":\"%s\","
        "\"timestamp\":%lu,"
        "\"lane1\":{"
            "\"total\":%u,"
            "\"class_x\":%u,\"class_a\":%u,\"class_b\":%u,"
            "\"class_c\":%u,\"class_d\":%u,\"class_e\":%u,"
            "\"avg_speed\":%u,"
            "\"occupancy\":%.2f"
        "},"
        "\"lane2\":{"
            "\"total\":%u,"
            "\"class_x\":%u,\"class_a\":%u,\"class_b\":%u,"
            "\"class_c\":%u,\"class_d\":%u,\"class_e\":%u,"
            "\"avg_speed\":%u,"
            "\"occupancy\":%.2f"
        "},"
        "\"environment\":{"
            "\"temperature\":%.1f,"
            "\"humidity\":%.1f,"
            "\"battery_voltage\":%.2f"
        "},"
        "\"status\":{"
            "\"sensor_status\":\"OK\","
            "\"uptime\":%lu"
        "}"
        "}",
        DEFAULT_DEVICE_ID,
        system_tick / 1000,
        lane1->total_vehicles,
        lane1->class_X.count, lane1->class_A.count, lane1->class_B.count,
        lane1->class_C.count, lane1->class_D.count, lane1->class_E.count,
        lane1->class_A.avg_speed,
        lane1->occupancy_rate,
        lane2->total_vehicles,
        lane2->class_X.count, lane2->class_A.count, lane2->class_B.count,
        lane2->class_C.count, lane2->class_D.count, lane2->class_E.count,
        lane2->class_A.avg_speed,
        lane2->occupancy_rate,
        temperature, humidity, battery_voltage,
        system_tick / 1000
    );

    printf("\r\n[DATA] JSON Payload (%d bytes):\r\n%s\r\n", json_len, json_buffer);

    // Send via SIM800L
    if (SIM800L_SendJSON(json_buffer) == HAL_OK) {
        printf("[SUCCESS] Data sent to server successfully!\r\n");
    } else {
        printf("[ERROR] Failed to send data to server!\r\n");
    }
}

/**
  * @brief  Process console command
  */
static void Process_Console_Command(char *cmd)
{
    if (strcmp(cmd, "help") == 0) {
        Print_Console_Menu();
    }
    else if (strcmp(cmd, "status") == 0) {
        printf("\r\n=== SYSTEM STATUS ===\r\n");
        printf("Device ID: %s\r\n", DEFAULT_DEVICE_ID);
        printf("Firmware: %s\r\n", FIRMWARE_VERSION);
        printf("Uptime: %lu seconds\r\n", system_tick / 1000);
        printf("Battery: %.2f V\r\n", battery_voltage);
        printf("Temperature: %.1f C\r\n", temperature);
        printf("Humidity: %.1f %%\r\n", humidity);
        printf("Lane 1 Count: %u vehicles\r\n", lane1_count);
        printf("Lane 2 Count: %u vehicles\r\n", lane2_count);
        printf("Next send: %lu seconds\r\n", (DATA_SEND_INTERVAL - (system_tick - last_send_time)) / 1000);
    }
    else if (strcmp(cmd, "calibrate") == 0) {
        printf("\r\n[INFO] Starting sensor calibration...\r\n");
        Sensor_Calibrate();
        printf("[SUCCESS] Calibration complete!\r\n");
    }
    else if (strcmp(cmd, "send") == 0) {
        printf("\r\n[INFO] Manual data transmission requested...\r\n");
        Process_10min_Tasks();
    }
    else if (strcmp(cmd, "reset") == 0) {
        printf("\r\n[INFO] System reset requested. Rebooting in 3 seconds...\r\n");
        HAL_Delay(3000);
        NVIC_SystemReset();
    }
    else {
        printf("\r\nUnknown command: '%s'. Type 'help' for available commands.\r\n", cmd);
    }
}

